  let appointmentFilter = 'all';
  let faqFilter = 'all';
  let faqSearch = '';
  let treatmentSearch = '';
  let treatmentCategory = 'All treatments';
  let treatmentSort = 'featured';
  let compareTreatmentIds = [];
  let booking = emptyBooking();
  let chatOpen = false;
  let chatMessages = [];
  let lastRoute = '';
  let drawerOpen = false;
