    if(form.id==='admin-auth-form'){e.preventDefault();if(!form.reportValidity())return;const fd=new FormData(form);const submit=form.querySelector('button[type="submit"]');if(submit){submit.disabled=true;submit.textContent='Verifying staff access…';}(async()=>{try{const result=await window.AurelleCloud.signInAdmin(String(fd.get('email')).trim(),String(fd.get('password')));firebaseUser=window.AurelleCloud.getUser();firebaseAdmin=!!result.isAdmin;const remote=await window.AurelleCloud.loadAdminWorkspace();if(remote.workspace)applyAdminCloud(remote);else{const oldAppointments=remote.appointments||[];const oldEnquiries=remote.enquiries||[];data=defaultData();data.appointments=oldAppointments;data.enquiries=oldEnquiries;await window.AurelleCloud.saveAdminWorkspace(JSON.parse(JSON.stringify(data)));}const latest=await window.AurelleCloud.loadAdminWorkspace();data.appointments=latest.appointments;data.enquiries=latest.enquiries;if(!cloudAdminUnsubscribe)cloudAdminUnsubscribe=window.AurelleCloud.watchAdminCollections((kind,items)=>{if(kind==='appointments')data.appointments=items;if(kind==='enquiries')data.enquiries=items;if(routeInfo().path==='/admin')render();},()=>{});adminTab='overview';render();go('/admin');toast('Staff access verified','The authorized Firebase workspace is ready.','success');}catch(err){toast('Staff sign-in failed',err?.message||'Check the credentials, administrator role, and Firebase rules.','error');}finally{if(submit){submit.disabled=false;submit.innerHTML='Sign in to operations '+icon('arrow');}}})();return;}
    if(form.id==='patient-auth-form'){e.preventDefault();if(!form.reportValidity())return;const fd=new FormData(form);const mode=form.dataset.mode;const submit=form.querySelector('button[type="submit"]');if(submit){submit.disabled=true;submit.textContent=mode==='register'?'Creating account…':'Signing in…';}(async()=>{try{let result;if(mode==='register')result=await window.AurelleCloud.register(String(fd.get('name')).trim(),String(fd.get('email')).trim(),String(fd.get('password')));else result=await window.AurelleCloud.signIn(String(fd.get('email')).trim(),String(fd.get('password')));firebaseUser=window.AurelleCloud.getUser();firebaseAdmin=!!result.isAdmin;data.appointments=await window.AurelleCloud.loadOwnAppointments();toast(mode==='register'?'Account created':'Signed in','Firebase Authentication verified your account.','success');go('/patient-dashboard');render();}catch(err){toast(mode==='register'?'Could not create account':'Sign-in failed',authErrorMessage(err),'error');}finally{if(submit){submit.disabled=false;submit.innerHTML=(mode==='register'?'Create patient account':'Sign in securely')+' '+icon('arrow');}}})();return;}
    if(form.id==='forgot-form'){e.preventDefault();if(!form.reportValidity())return;const fd=new FormData(form);const submit=form.querySelector('button[type="submit"]');if(submit){submit.disabled=true;submit.textContent='Sending reset email…';}(async()=>{try{await window.AurelleCloud.resetPassword(String(fd.get('email')).trim());toast('Reset email requested','If the address is registered and email delivery is configured, Firebase will send password reset instructions.','success');}catch(err){toast('Could not request password reset',authErrorMessage(err),'error');}finally{if(submit){submit.disabled=false;submit.innerHTML='Send reset instructions '+icon('arrow');}}})();return;}
    if(form.id==='treatment-modal-form'){e.preventDefault();saveTreatmentForm(form);return;}
    if(form.id==='dentist-modal-form'){e.preventDefault();saveDentistForm(form);return;}
